const request = $input.first()?.json ?? {};
const body = request.body && typeof request.body === 'object' ? request.body : request;
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const tenantId = String(headers['x-tenant-id'] ?? headers['X-Tenant-Id'] ?? '').trim();
const question = String(body.project_question ?? '').trim();
const resumeRunId = String(body.resume_run_id ?? '').trim();
const list = (value) => Array.isArray(value) ? [...new Set(value.map((item) => String(item || '').trim()).filter(Boolean))] : [];
const accessGroups = [...new Set(String(headers['x-access-groups'] ?? headers['X-Access-Groups'] ?? '').split(',').map((item) => item.trim()).filter(Boolean))];
const errors = [];
if (!tenantId) errors.push('x-tenant-id is required');
if (!resumeRunId && !question) errors.push('project_question is required');
if (resumeRunId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(resumeRunId)) errors.push('resume_run_id must be a UUID');
return [{ json: {
  valid: errors.length === 0,
  errors,
  project_question: question,
  history_id: String(body.history_id ?? '').trim(),
  resume_run_id: resumeRunId,
  tenant_id: tenantId,
  access_groups: accessGroups,
  project_types: list(body.project_types),
  geography: list(body.geography),
  metadata_filter: body.metadata_filter && typeof body.metadata_filter === 'object' && !Array.isArray(body.metadata_filter) ? body.metadata_filter : {},
  deliver_to_feishu: body.deliver_to_feishu === true,
  requested_at: new Date().toISOString(),
} }];

const submitted = $('Normalize Trusted Request').first().json;
const run = $input.first()?.json ?? {};
const stored = run.request && typeof run.request === 'object' ? run.request : submitted;
const runId = String(run.run_id ?? '').trim();
if (!runId) throw new Error('analysis_run_not_resumable');
return [{ json: { ...stored, run_id: runId } }];
